using UnityEngine;
using UnityEngine.Tilemaps;
using UnityEditor;
using UnityEditor.SceneManagement;

public class SetupMultiTierTilemaps
{
    public static string Execute()
    {
        GameObject gridObj = GameObject.Find("Grid_CatwalkFloor");
        if (gridObj == null)
        {
            gridObj = new GameObject("Grid_CatwalkFloor", typeof(Grid));
        }

        // 1. Solid Ground Tilemap (Y = -6)
        GameObject groundTmObj = GameObject.Find("Grid_CatwalkFloor/Tilemap_CatwalkFloor");
        if (groundTmObj == null)
        {
            groundTmObj = new GameObject("Tilemap_CatwalkFloor");
            groundTmObj.transform.SetParent(gridObj.transform, false);
        }
        groundTmObj.layer = 8;
        Tilemap groundTm = groundTmObj.GetComponent<Tilemap>();
        if (groundTm == null) groundTm = groundTmObj.AddComponent<Tilemap>();
        TilemapRenderer groundR = groundTmObj.GetComponent<TilemapRenderer>();
        if (groundR == null) groundR = groundTmObj.AddComponent<TilemapRenderer>();
        groundR.sortingLayerName = "Default";
        groundR.sortingOrder = 5;
        TilemapCollider2D groundCol = groundTmObj.GetComponent<TilemapCollider2D>();
        if (groundCol == null) groundCol = groundTmObj.AddComponent<TilemapCollider2D>();

        TileBase floorTile = AssetDatabase.LoadAssetAtPath<TileBase>("Assets/Art/Tilemaps/Lab_Platform_Surface.asset") ??
                              AssetDatabase.LoadAssetAtPath<TileBase>("Assets/Art/Tilemaps/Lab_Floor_Tile.asset");
        TileBase glowTile = AssetDatabase.LoadAssetAtPath<TileBase>("Assets/Art/Tilemaps/Lab_Platform_CyanGlow.asset");
        TileBase edgeL = AssetDatabase.LoadAssetAtPath<TileBase>("Assets/Art/Tilemaps/Lab_Platform_Edge_Left.asset");
        TileBase edgeR = AssetDatabase.LoadAssetAtPath<TileBase>("Assets/Art/Tilemaps/Lab_Platform_Edge_Right.asset");

        if (floorTile != null)
        {
            for (int x = -16; x <= 16; x++)
            {
                TileBase t = (Mathf.Abs(x) % 4 == 0 && glowTile != null) ? glowTile : floorTile;
                groundTm.SetTile(new Vector3Int(x, -6, 0), t);
            }
        }

        // 2. One-Way Elevated Platforms Tilemap
        GameObject oneWayTmObj = GameObject.Find("Grid_CatwalkFloor/Tilemap_OneWayPlatforms");
        if (oneWayTmObj == null)
        {
            oneWayTmObj = new GameObject("Tilemap_OneWayPlatforms");
            oneWayTmObj.transform.SetParent(gridObj.transform, false);
        }
        oneWayTmObj.layer = 8;

        Tilemap oneWayTm = oneWayTmObj.GetComponent<Tilemap>();
        if (oneWayTm == null) oneWayTm = oneWayTmObj.AddComponent<Tilemap>();
        TilemapRenderer oneWayR = oneWayTmObj.GetComponent<TilemapRenderer>();
        if (oneWayR == null) oneWayR = oneWayTmObj.AddComponent<TilemapRenderer>();
        oneWayR.sortingLayerName = "Default";
        oneWayR.sortingOrder = 6;

        TilemapCollider2D tmCol = oneWayTmObj.GetComponent<TilemapCollider2D>();
        if (tmCol == null) tmCol = oneWayTmObj.AddComponent<TilemapCollider2D>();
        tmCol.usedByEffector = true;

        PlatformEffector2D effector = oneWayTmObj.GetComponent<PlatformEffector2D>();
        if (effector == null) effector = oneWayTmObj.AddComponent<PlatformEffector2D>();
        effector.useOneWay = true;
        effector.useOneWayGrouping = true;
        effector.surfaceArc = 170f;
        effector.useSideFriction = false;
        effector.useSideBounce = false;

        Rigidbody2D rb = oneWayTmObj.GetComponent<Rigidbody2D>();
        if (rb == null) rb = oneWayTmObj.AddComponent<Rigidbody2D>();
        rb.bodyType = RigidbodyType2D.Static;

        oneWayTm.ClearAllTiles();

        void PaintPlatform(int minX, int maxX, int y)
        {
            if (edgeL != null) oneWayTm.SetTile(new Vector3Int(minX, y, 0), edgeL);
            for (int x = minX + 1; x < maxX; x++)
            {
                TileBase t = (x == (minX + maxX) / 2 && glowTile != null) ? glowTile : (floorTile ?? glowTile);
                oneWayTm.SetTile(new Vector3Int(x, y, 0), t);
            }
            if (edgeR != null) oneWayTm.SetTile(new Vector3Int(maxX, y, 0), edgeR);
        }

        // Mid Left Catwalk (Y = -3)
        PaintPlatform(-13, -7, -3);

        // Center Dais / Terminal (Y = -2)
        PaintPlatform(-3, 3, -2);

        // Mid Right Catwalk (Y = -3)
        PaintPlatform(7, 13, -3);

        // Upper Vantage Ledges (Y = 1)
        PaintPlatform(-5, 5, 1);

        EditorSceneManager.MarkSceneDirty(EditorSceneManager.GetActiveScene());
        EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());

        return "Multi-tier platforms created successfully!";
    }
}
